const mod = require('child_process');
const entree = $input.first().json;
const prompt = String(entree.prompt || '');
const debut = Date.now();

let sortie = '';
let sortieErreur = null;
let erreur = null;
let codeSortie = 0;

try {
  sortie = String(mod.execFileSync(
    'claude-run',
    ['-p', prompt, '--output-format', 'json', '--model', 'sonnet'],
    { encoding: 'utf8', timeout: 270000, maxBuffer: 33554432, cwd: '/tmp' }
  ));
} catch (err) {
  codeSortie = (err && typeof err.status === 'number') ? err.status : -1;
  erreur = String((err && err.message) || err).slice(0, 400);
  sortie = (err && err.stdout) ? String(err.stdout) : '';
  sortieErreur = (err && err.stderr) ? String(err.stderr).slice(0, 2000) : null;
}

return [{ json: {
  sortie: sortie,
  sortieErreur: sortieErreur,
  erreur: erreur,
  codeSortie: codeSortie,
  dureeAppelMs: Date.now() - debut,
  contexte: entree.contexte
} }];

const brut = $input.first().json;
const sortie = String(brut.sortie || '').trim();

if (!sortie) {
  return [{ json: { ok: false, etape: 'appel', codeSortie: brut.codeSortie, erreur: brut.erreur, sortieErreur: brut.sortieErreur, dureeAppelMs: brut.dureeAppelMs, contexte: brut.contexte } }];
}

let enveloppe;
try {
  enveloppe = JSON.parse(sortie);
} catch (e) {
  return [{ json: { ok: false, etape: 'enveloppe', erreur: String(e), sortie: sortie.slice(0, 3000), contexte: brut.contexte } }];
}

if (enveloppe.is_error || brut.codeSortie !== 0) {
  return [{ json: { ok: false, etape: 'claude', codeSortie: brut.codeSortie, erreur: String(enveloppe.result || enveloppe.subtype || brut.erreur || 'erreur inconnue').slice(0, 2000), contexte: brut.contexte } }];
}

const texte = typeof enveloppe.result === 'string' ? enveloppe.result : sortie;
const fence = String.fromCharCode(96, 96, 96);
let nettoye = texte.trim();
while (nettoye.indexOf(fence) === 0) {
  nettoye = nettoye.slice(fence.length).replace(/^json/i, '').trim();
}
const finFence = nettoye.lastIndexOf(fence);
if (finFence > 0) nettoye = nettoye.slice(0, finFence).trim();

const d = nettoye.indexOf('{');
const f = nettoye.lastIndexOf('}');
let charge = null;
let erreurJson = null;
if (d >= 0 && f > d) {
  try { charge = JSON.parse(nettoye.slice(d, f + 1)); }
  catch (e) { erreurJson = String(e); }
} else {
  erreurJson = 'aucun objet JSON trouve dans la reponse';
}

return [{ json: {
  ok: charge !== null,
  etape: charge !== null ? 'ok' : 'json',
  erreur: erreurJson,
  reponse: charge,
  texteBrut: texte,
  contexte: brut.contexte,
  dureeAppelMs: brut.dureeAppelMs,
  coutUsd: enveloppe.total_cost_usd === undefined ? null : enveloppe.total_cost_usd,
  cacheEcrit: (enveloppe.usage && enveloppe.usage.cache_creation_input_tokens) || 0,
  cacheLu: (enveloppe.usage && enveloppe.usage.cache_read_input_tokens) || 0
} }];

const r = $input.first().json;

if (!r.ok || !r.reponse) {
  return [{ json: { verdict: 'ECHEC', etape: r.etape, erreur: r.erreur, dureeAppelMs: r.dureeAppelMs } }];
}

const ctx = r.contexte || {};
const objet = String(r.reponse.objet || '');
const corps = String(r.reponse.corps || '');
const cadratin = String.fromCharCode(8212);
const demiCadratin = String.fromCharCode(8211);

function aplatir(s) {
  return String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();
}
const corpsPlat = aplatir(corps);

const mots = corps.trim() ? corps.trim().split(/\s+/).length : 0;

const blocs = corps.split(/\n\s*\n/).map(function (p) { return p.trim(); }).filter(Boolean);
const dernier = blocs.length ? blocs[blocs.length - 1] : '';
const signaturePresente = /^(cordialement|bien cordialement|respectueusement|sincerement|salutations)/i.test(aplatir(dernier));
const paragraphes = signaturePresente ? blocs.length - 1 : blocs.length;

const violations = [];
function verifier(condition, libelle) { if (!condition) violations.push(libelle); }

verifier(objet.length > 0 && objet.length <= 60, 'objet hors limite (' + objet.length + ' caracteres, max 60)');
verifier(!/^\s*(re\s*:|relance\s*:)/i.test(objet), 'objet prefixe par Re: ou Relance:');
verifier(mots > 0 && mots <= 90, 'corps hors limite (' + mots + ' mots, max 90)');
verifier(paragraphes <= 3, 'corps en ' + paragraphes + ' paragraphes hors signature (max 3)');
verifier(signaturePresente, 'formule de politesse finale absente');
verifier(corps.indexOf(cadratin) === -1 && objet.indexOf(cadratin) === -1, 'tiret cadratin present');
verifier(corps.indexOf(demiCadratin) === -1 && objet.indexOf(demiCadratin) === -1, 'tiret demi-cadratin present');
verifier(!/[*#\[\]]/.test(corps), 'markdown present dans le corps');
verifier(!/<[a-z][^>]*>/i.test(corps), 'balise HTML presente dans le corps');
verifier(corpsPlat.indexOf(aplatir(ctx.entreprise)) !== -1, 'entreprise non mentionnee dans le corps');
verifier(corpsPlat.indexOf(aplatir(ctx.poste)) !== -1, 'poste non mentionne dans le corps');
verifier(aplatir(corps.trim().slice(-60)).indexOf(aplatir(ctx.candidateName)) !== -1, 'ne se termine pas par le nom du candidat');
verifier(!/(@|\+33|0[1-9](\s?\d{2}){4})/.test(corps), 'courriel ou telephone ajoute dans le corps');
verifier(!/(deux ans|un an|an et demi|ans d'experience|annees d'experience)/i.test(corpsPlat), 'anciennete inventee');
verifier(!/(entretien|appel telephonique|notre echange)/i.test(corpsPlat), 'echange passe invente');

return [{ json: {
  verdict: violations.length === 0 ? 'CONFORME' : 'NON CONFORME',
  controles: 15,
  violations: violations,
  accentue: corps !== corpsPlat.normalize('NFC') && /[à-ÿ]/.test(corps),
  objet: objet,
  objetCaracteres: objet.length,
  corps: corps,
  corpsMots: mots,
  corpsParagraphes: paragraphes,
  dureeAppelMs: r.dureeAppelMs,
  coutUsd: r.coutUsd,
  cacheEcrit: r.cacheEcrit,
  cacheLu: r.cacheLu
} }];
